using System.Security.Claims; using MaintenancePRO.Api.Contracts; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/interventions"),Authorize]
public sealed class InterventionsController(AppDbContext db,UserManager<ApplicationUser> users):ControllerBase {
 [HttpGet] public async Task<IActionResult> List([FromQuery]InterventionStatus? status,[FromQuery]int page=1,[FromQuery]int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Interventions.AsNoTracking().Include(x=>x.Equipment).Include(x=>x.Breakdown).AsQueryable();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.Technician))q=q.Where(x=>x.AssignedTechnicianId==uid);else if(User.IsInRole(AppRoles.User))q=q.Where(x=>x.CreatedByUserId==uid);if(status.HasValue)q=q.Where(x=>x.Status==status);var total=await q.CountAsync();return Ok(new{page,pageSize,total,items=await q.OrderByDescending(x=>x.CreatedUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync()});}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Interventions.AsNoTracking().Include(x=>x.Equipment).Include(x=>x.Breakdown).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();if(!CanRead(x))return Forbid();return Ok(x);}
 [HttpPost,Authorize(Policy="ManageMaintenance")] public async Task<IActionResult> Create(CreateInterventionRequest r){var b=await db.Breakdowns.Include(x=>x.Equipment).FirstOrDefaultAsync(x=>x.Id==r.BreakdownId);if(b==null)return BadRequest(new{message="Panne inconnue."});if(b.Status is BreakdownStatus.Resolved or BreakdownStatus.Closed or BreakdownStatus.Rejected)return Conflict(new{message="Cette panne n'est plus ouverte."});var x=new Intervention{BreakdownId=b.Id,EquipmentId=b.EquipmentId,Title=r.Title.Trim(),WorkDescription=r.WorkDescription.Trim(),CreatedByUserId=User.FindFirstValue(ClaimTypes.NameIdentifier)!};db.Interventions.Add(x);b.Status=BreakdownStatus.InMaintenance;if(b.Equipment!=null)b.Equipment.Status=EquipmentStatus.InService;Audit("InterventionCreated",x.Id.ToString());await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPatch("{id:int}"),Authorize(Policy="ManageMaintenance")] public async Task<IActionResult> Update(int id,UpdateInterventionRequest r){var x=await db.Interventions.Include(x=>x.Breakdown).Include(x=>x.Equipment).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.Technician)&&x.AssignedTechnicianId!=uid)return Forbid();
 if(r.AssignedTechnicianId!=null){if(!User.IsInRole(AppRoles.Admin)&&!User.IsInRole(AppRoles.Supervisor))return Forbid();var tech=await users.FindByIdAsync(r.AssignedTechnicianId);if(tech==null||tech.Status!=AccountStatus.Active||!await users.IsInRoleAsync(tech,AppRoles.Technician))return BadRequest(new{message="Technicien actif invalide."});x.AssignedTechnicianId=tech.Id;}
 if(!CanTransition(x.Status,r.Status,User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)))return Conflict(new{message="Transition d'intervention non autorisée."});
 if(r.Resolution is {Length:>3000})return BadRequest(new{message="Résolution trop longue."});if(r.LaborHours<0||r.Cost<0)return BadRequest(new{message="Heures et coût ne peuvent pas être négatifs."});
 x.Status=r.Status;if(r.Resolution!=null)x.Resolution=r.Resolution.Trim();if(r.LaborHours.HasValue)x.LaborHours=r.LaborHours;if(r.Cost.HasValue)x.Cost=r.Cost;
 if(r.Status==InterventionStatus.InProgress)x.StartedUtc??=DateTime.UtcNow;
 if(r.Status==InterventionStatus.Completed){if(string.IsNullOrWhiteSpace(x.Resolution))return BadRequest(new{message="Une résolution est obligatoire pour terminer l'intervention."});x.CompletedUtc=DateTime.UtcNow;if(x.Breakdown!=null){x.Breakdown.Status=BreakdownStatus.Resolved;x.Breakdown.ResolvedUtc=DateTime.UtcNow;}if(x.Equipment!=null){x.Equipment.Status=EquipmentStatus.Available;x.Equipment.UpdatedUtc=DateTime.UtcNow;}}
 Audit("InterventionUpdated",id.ToString());await db.SaveChangesAsync();return Ok(x);}
 private static bool CanTransition(InterventionStatus a,InterventionStatus b,bool manager)=>(a switch{InterventionStatus.Planned=>b is InterventionStatus.Assigned or InterventionStatus.Cancelled or InterventionStatus.Rejected,InterventionStatus.Assigned=>b is InterventionStatus.InProgress or InterventionStatus.Cancelled,InterventionStatus.InProgress=>b is InterventionStatus.Paused or InterventionStatus.Completed,InterventionStatus.Paused=>b is InterventionStatus.InProgress or InterventionStatus.Cancelled, _=>false}) || (manager&&b==InterventionStatus.Cancelled);
 private bool CanRead(Intervention x){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)||x.CreatedByUserId==uid||x.AssignedTechnicianId==uid;}
 private void Audit(string a,string id)=>db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action=a,EntityType="Intervention",EntityId=id,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()});
}
